#pragma once

#include "slic3r/GUI/JusPrin/Agent/ProjectPersistence.hpp"
#include "slic3r/GUI/JusPrin/CanvasPresentationController.hpp"
#include "slic3r/GUI/JusPrin/Agent/AgentHost.hpp"
#include "slic3r/GUI/JusPrin/PrintIssues/IssueContext.hpp"
#include "slic3r/GUI/JusPrin/PrintIssues/IssueOverlay.hpp"
#include "slic3r/GUI/JusPrin/PrintIssues/PrintIssueMonitor.hpp"
#include "slic3r/GUI/JusPrin/PrintIssues/WorkFeed.hpp"
#include "slic3r/GUI/JusPrin/Workspace/OrcaWorkspaceAdapter.hpp"
#include "slic3r/GUI/JusPrin/Workspace/ProjectAutosave.hpp"

#include <memory>
#include <functional>
#include <string>
#include <wx/event.h>
#include <wx/string.h>
#include <wx/timer.h>

class wxSizer;
class wxBoxSizer;
class wxWindow;
class Notebook;

namespace Slic3r::GUI {
class MainFrame;
class Plater;
}

namespace Slic3r::GUI::JusPrin {

class AgentPane;
class LeftPane;
class ShellTheme;
class StatusRow;

namespace Home {
class HomeWebView;
}

namespace PrinterSetup {
class PrinterPanel;
}

// Installs the JusPrin production presentation inside the existing MainFrame
// layout and can restore the stock presentation exactly. The stock widget
// hierarchy stays constructed and functional: the Notebook keeps its pages and
// selection flow, only its tab strip is hidden, and the Plater sidebar is held
// hidden through Plater's sidebar-availability policy.
class ShellController : public wxEvtHandler
{
public:
    enum class ReimportDecision { OpenExisting, CreateNew, Cancel };
    ShellController();
    ~ShellController();

    ShellController(const ShellController&) = delete;
    ShellController& operator=(const ShellController&) = delete;

    // Throws on failure after restoring any partial change; the caller may
    // then continue with the untouched stock presentation.
    void install(MainFrame& frame, Notebook& tabpanel, wxSizer& main_sizer);
    void uninstall();
    bool is_installed() const { return m_installed; }

    StatusRow* status_row() const { return m_status_row; }
    Home::HomeWebView* home_view() const { return m_home; }
    PrinterSetup::PrinterPanel* printer_panel() const { return m_printer_panel; }
    AgentPane* agent_pane() const { return m_agent_pane; }
    PrintIssues::WorkFeed* work_feed() const { return m_work_feed.get(); }
    bool agent_pane_collapsed() const { return m_agent_pane_collapsed; }
    LeftPane* left_pane() const { return m_left_pane; }
    // The Prepare canvas's presentation, for the integration harness to drive
    // the tool strip and the value card the way a pointer does.
    const CanvasPresentationController& prepare_canvas_presentation() const { return m_prepare_canvas_presentation; }
    Workspace::IWorkspace* workspace() const { return m_workspace.get(); }

    // What OrcaSlicer currently reports about the active plate, and its
    // pill, list and bubble on the Prepare canvas. Null while not installed.
    PrintIssues::PrintIssueMonitor* print_issues() const { return m_print_issues.get(); }
    PrintIssues::IssueOverlay*      issue_overlay() const { return m_issue_overlay.get(); }
    struct IssueSubmission
    {
        // "started", "queued", "duplicate", or why nothing was sent:
        // "expired" (OrcaSlicer no longer reports the issue), "unchecked"
        // (it has not validated the latest edit), "agent_not_set_up" (there
        // is no assistant to answer), "busy" (a reply is being written), or
        // the chat's own refusal code.
        std::string               outcome;
        PrintIssues::IssueMessage message;
    };
    // Sends the issue to the project chat as the person's own message and
    // opens the chat pane. The issue is looked up again at the moment of the
    // press, so one that has cleared or gone stale since it was drawn is not sent.
    IssueSubmission submit_issue(const std::string& issue_id, const std::string& request_sentence);
    // What a press of either button does with no assistant set up: says so
    // and offers to open the chat panel's setup. Returns whether the person
    // took the offer.
    bool offer_agent_setup();
    Agent::ProjectPersistence* persistence() const { return m_persistence.get(); }
    Workspace::ProjectAutosave* autosave() const { return m_autosave.get(); }
    void set_reimport_confirmation(std::function<ReimportDecision()> confirmation)
        { m_reimport_confirmation = std::move(confirmation); }

    void apply_current_appearance();

    // Closing the Agent panel hides it and its divider; the panel keeps its
    // conversation, its loaded page, and its MCP runtime while hidden, and
    // reopening restores the width it last held this session.
    void set_agent_pane_collapsed(bool collapsed);
    // A person's own choice, remembered across the visits to Home that
    // collapse the pane on their behalf.
    void toggle_agent_pane()
    {
        m_agent_pane_user_collapsed = !m_agent_pane_collapsed;
        set_agent_pane_collapsed(m_agent_pane_user_collapsed);
    }
    bool is_agent_pane_collapsed() const { return m_agent_pane_collapsed; }
    // Mirrored left-panel treatment: the open copy lives in its own header
    // row; the collapsed copy lives at the same screen edge in Project header.
    void set_left_pane_collapsed(bool collapsed);
    void toggle_left_pane() { set_left_pane_collapsed(!m_left_pane_collapsed); }
    bool is_left_pane_collapsed() const { return m_left_pane_collapsed; }
    // Takes the person to the Agent panel's own setup flow from anywhere in
    // the shell: leaves Home for the workspace, opens the panel as their
    // choice, and asks the page to open setup.
    void open_agent_setup();

    // A throwaway AgentWebView embedded elsewhere (the Add a printer dialog's
    // own setup flow) just wrote a working agent config that the docked
    // pane's own AgentHost instance has no way to learn about on its own.
    // on_page_changed() re-derives and pushes fresh availability into the
    // docked pane the next time it would become relevant again, the same way
    // it already refreshes Home's gallery on return.
    void mark_agent_config_possibly_changed() { m_agent_config_possibly_changed = true; }

    // Orca's own printer wizard ("set it up myself") runs from a CallAfter,
    // decoupled from the add-printer request that opened it, so nothing else
    // tells Home about the printer it names. The caller asks for this refresh
    // once the wizard flow (and any naming it does) has actually finished.
    // `added` is a successful Add's saved facts, forwarded so Home can lead
    // its column with that printer and say what it assumed; every other
    // caller passes none.

    // Opens a fresh temporary task chat over the current workspace. The
    // Notebook keeps its selection, so Back restores the same Home, Prepare,
    // or Preview screen without rebuilding it.
    void open_printer_conversation(const std::string& printer_name = {}, bool connect = false);
    // Opens a filament's chat for one slot. `preset` is the slot's filament
    // preset by name; `shown` is what the header calls it.
    void open_filament_help(std::size_t slot, const std::string& preset, const std::string& shown);

private:
    void on_frame_destroy(wxWindowDestroyEvent& event);
    // Applies what the Notebook's current page implies for the shell: Home
    // refreshes its gallery and takes the Agent panel off the screen.
    void on_page_changed();
    void on_notebook_page_changed(wxBookCtrlEvent& event);
    void on_frame_size(wxSizeEvent& event);
    void show_task_panel();
    void restore_task_panel();
    // The width the pane may hold right now: at least its own minimum, and no
    // more than what the frame can spare beside a usable workspace.
    int  agent_pane_width_within(int width) const;
    void request_agent_pane_width(int width);
    void apply_agent_pane_width();
    int  left_pane_width_within(int width) const;
    void request_left_pane_width(int width);
    void apply_left_pane_width();

    const ShellTheme* m_theme{nullptr};
    wxTimer m_runtime_timer{this};

    MainFrame* m_frame{nullptr};
    Notebook*  m_tabpanel{nullptr};
    wxSizer*   m_main_sizer{nullptr};
    Plater*    m_plater{nullptr};
    std::function<ReimportDecision()> m_reimport_confirmation;

    StatusRow* m_status_row{nullptr};
    AgentPane* m_agent_pane{nullptr};
    // The Agent page owns the open-pane toggle in its existing header. The
    // project header owns the collapsed copy; only one is visible at a time.
    // The Plates / Project pane, left of the workspace; shown on Prepare only.
    LeftPane*  m_left_pane{nullptr};
    // Shown in the Notebook's slot while the Notebook's selection is tpHome.
    Home::HomeWebView* m_home{nullptr};
    // Fresh in-memory printer or filament task chat, shown over the workspace.
    PrinterSetup::PrinterPanel* m_printer_panel{nullptr};
    wxWindow* m_left_resize_handle{nullptr};
    wxWindow* m_agent_resize_handle{nullptr};
    wxBoxSizer* m_center_sizer{nullptr};
    // The project header and canvas share the center column. The Plates /
    // Project and Agent panes are independent full-height columns beside it.
    wxBoxSizer* m_project_sizer{nullptr};
    // Home and the Notebook share this slot: exactly one is shown.
    wxBoxSizer* m_workspace_sizer{nullptr};
    int m_left_pane_preferred_width{0};
    int m_agent_pane_preferred_width{0};
    bool m_left_pane_collapsed{true};
    bool m_agent_pane_collapsed{false};
    // What the person last asked for, as opposed to what Home imposes.
    bool m_agent_pane_user_collapsed{false};
    // Set by mark_agent_config_possibly_changed(), consumed by on_page_changed().
    bool m_agent_config_possibly_changed{false};
    bool m_task_open{false};
    int  m_task_origin_tab{-1};

    // The one workspace projection consumed by the Agent bridge. It must be
    // constructed before the AgentPane and outlive it.
    std::unique_ptr<Workspace::OrcaWorkspaceAdapter> m_workspace;
    // Project-owned conversation state; constructed
    // after the workspace and before the pane, destroyed in reverse.
    std::unique_ptr<Agent::ProjectPersistence> m_persistence;
    std::unique_ptr<Workspace::ProjectAutosave> m_autosave;
    // The version pinned before a model turn's first edit; every later edit
    // of the turn links to it, and the turn's end clears it.
    std::string m_turn_before_version;
    std::string m_autosave_status_key;
    std::string m_timeline_version_head;
    std::uint64_t m_timeline_document_revision{0};
    wxString m_saved_frame_title;

    bool m_installed{false};
    bool m_saved_collapse_toolbar_enabled{false};
    bool m_saved_auto_preview_after_slice{true};
    bool m_saved_show_config_wizard_on_startup{true};
    CanvasPresentationController m_prepare_canvas_presentation;
    std::unique_ptr<PrintIssues::PrintIssueMonitor> m_print_issues;
    std::unique_ptr<PrintIssues::IssueOverlay>      m_issue_overlay;
    std::unique_ptr<PrintIssues::WorkFeed>          m_work_feed;
};

// The one MainFrame attachment point. Decides whether the shell should be
// installed for this session, installs it, and falls back to the untouched
// stock presentation when installation fails. Never throws.
void attach_shell(MainFrame& frame, Notebook* tabpanel, wxSizer* main_sizer);

// The controller installed by attach_shell, if any (used by tests and later
// phases; returns nullptr in stock mode).
ShellController* installed_shell();

// Removes the shell installed by attach_shell and restores the stock
// presentation. Safe to call when no shell is installed.
void detach_shell();

} // namespace Slic3r::GUI::JusPrin
#pragma once

#include <vector>

namespace Slic3r::GUI::JusPrin {

enum class PrintAction { Slice, SliceAll, Cancel, CheckPrint, Print, PrintAll, Export };

struct PrintActionState
{
    bool slicing{false}, sliced{false}, can_slice{false}, can_slice_all{false};
    bool can_print{false}, can_print_all{false}, can_export{false};
    int plate_number{1}, plate_count{1}, sliced_count{0};
};

struct PrintActionItem { PrintAction action; bool enabled; };
struct PrimaryPrintAction
{
    PrintActionItem primary;
    std::vector<PrintActionItem> menu;
};

// The same reducer drives rendering, command eligibility and contract tests.
inline PrimaryPrintAction primary_print_action(const PrintActionState& state)
{
    PrimaryPrintAction result;
    if (state.slicing) {
        result.primary = {PrintAction::Cancel, false};
        result.menu = {{PrintAction::Cancel, true}};
    } else if (!state.sliced) {
        result.primary = {PrintAction::Slice, state.can_slice};
        if (state.plate_count > 1) result.menu.push_back({PrintAction::SliceAll, state.can_slice_all});
    } else {
        result.primary = {PrintAction::Print, state.can_print};
        result.menu = {{PrintAction::CheckPrint, true},
                       {PrintAction::PrintAll, state.plate_count > 1 && state.can_print_all},
                       {PrintAction::Export, state.can_export}};
    }
    return result;
}

} // namespace Slic3r::GUI::JusPrin
#pragma once

#include "ShellTheme.hpp"
#include "slic3r/GUI/Widgets/PopupWindow.hpp"
#include <wx/bitmap.h>

class wxGraphicsContext;
#include <wx/control.h>
#include <wx/weakref.h>
#include <functional>
#include <optional>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// Caret is the chip's own solid disclosure triangle; Down/Up/Right are the
// lighter strokes the menu rows use.
// PanelOpen and PanelClosed are the right pane's two states; PanelLeftOpen
// and PanelLeftClosed mirror the same glyph for the left pane.
enum class HeaderIcon { None, Back, Down, Up, Right, Caret, More, Printer, Monitor, Check, Eye, Lock, Slice, Slicing, Plates, Export, Print, Cancel,
                        PanelOpen, PanelClosed, PanelLeftOpen, PanelLeftClosed };

// Draws a semantic Lucide asset, or the product-specific solid caret/pane state,
// into a graphics context for shell surfaces that paint their own rows.
void draw_header_icon(wxGraphicsContext& gc, HeaderIcon icon, double x, double y, double size, const wxColour& color);

// ChipLeft and ChipRight are the two halves of the printer/filament chip. Each is
// a separate focus target, and each paints its own outer half of one shared
// outline, the way PrimaryLeft/PrimaryRight already split the print action.
enum class HeaderStyle { Quiet, ChipLeft, ChipRight, PrimaryLeft, PrimaryRight, Outline, Menu };

// A status is a colour plus a word, never a colour alone: the design system
// requires state to be readable without relying on hue.
enum class StatusTone { None, Neutral, Positive, Busy, Warning };

// One dot in a row of filament slots. A faded dot keeps its colour at low
// strength: a slot the current plate does not print with.
struct SlotDot
{
    wxColour colour;
    bool     faded{false};
};

// Everything a menu row can carry beyond its label. Grouped rather than spread
// over a dozen setters because HeaderMenu builds a row in one shot, and a row
// with no decoration should read as exactly that at the call site.
struct HeaderRowDecoration
{
    // Text ahead of everything else on the row, in the label's own face -- a
    // slot's number, which the design reads before the slot's dot.
    wxString lead;
    // Leading dot. Set with a valid colour for a filled swatch; set with an
    // invalid colour for the dashed outline of a colour nobody chose.
    std::optional<wxColour> dot;
    // A row of slot dots before the label, in slot order, then a grey "+n"
    // when slots were folded away. Small dots let many slots fit.
    std::vector<SlotDot> slot_dots;
    wxString             slot_more;
    bool                 small_slot_dots{false};
    // Right-aligned secondary text, in the label role.
    wxString   detail;
    // Draws the detail immediately after the label, separated by a middot,
    // instead of right-aligning it. The chip's nozzle reads as part of one
    // line -- "X1 Carbon · 0.4" -- while staying regular beside the bold
    // printer name, which one text run could not do.
    bool       detail_inline{false};
    // Second line under the label, in text/secondary.
    wxString   sub_label;
    bool       bold{false};
    bool       danger{false};
    bool       check{false};
    HeaderIcon trailing{HeaderIcon::None};
    StatusTone status{StatusTone::None};
    wxString   status_word;
};

// Fork-owned painting, with the same wxEVT_BUTTON contract as native controls.
// Each half of the split action remains a separate keyboard focus target.
class HeaderButton : public wxControl
{
public:
    HeaderButton(wxWindow* parent, const ShellTheme& theme, HeaderStyle style,
                 const wxString& label, HeaderIcon icon);
    void set_dark(bool dark);
    void set_icon(HeaderIcon icon);
    void set_status(bool visible, bool warning = false);
    void set_detail(const wxString& detail);
    void set_decoration(HeaderRowDecoration decoration);
    // A second, interactive glyph at the row's right end, revealed while the
    // row is hovered or selected. Clicking it -- or right-clicking the row --
    // raises wxEVT_MENU instead of wxEVT_BUTTON, so one row can carry a
    // secondary action without a second focusable control.
    void set_row_action(HeaderIcon icon);
    void set_row_action_label(const wxString& label);
    const wxString& row_action_label() const { return m_row_action_label; }
    bool has_row_action() const { return m_row_action != HeaderIcon::None || !m_row_action_label.empty(); }
    // Raises the row action as though its glyph had been clicked.
    void invoke_row_action();
    const HeaderRowDecoration& decoration() const { return m_decoration; }
    // Caps the label before it ellipsizes, so one long preset name cannot push
    // the rest of the header off the row. 0 means no cap.
    void set_label_cap(int cap_dip);
    void set_menu_selected(bool selected) { m_menu_selected = selected; Refresh(); }
    // A primary-left half squares its right edge only while a menu half sits beside it.
    void set_attached(bool attached) { m_attached = attached; Refresh(); }
    // A menu trigger holds a pressed fill and flips its chevron for as long as
    // its menu is open. HeaderMenu owns the flag; nothing else may set it.
    void set_open(bool open) { m_open = open; Refresh(); }
    bool is_open() const { return m_open; }
    // Whether the last activation came from Return/Space rather than a click.
    // A menu anchored here highlights its first row only in the keyboard case.
    bool activated_by_keyboard() const { return m_keyboard_activated; }
    void SetLabel(const wxString& label) override;
    bool Enable(bool enabled = true) override;
    wxSize DoGetBestSize() const override;
    // As with Orca's custom Button, macOS must ask the wx control rather
    // than the generic NSView whether it can become first responder.
    bool AcceptsFocus() const override { return true; }
    // Draws the control into an offscreen bitmap using the same code the paint
    // event uses, so appearance can be verified from inside the running
    // application in both modes without a screen capture.
    wxBitmap snapshot();

private:
    void paint(wxPaintEvent&);
    void draw(wxDC& dc, wxGraphicsContext& context, const wxSize& client);
    void activate(bool from_keyboard);
    const wxFont& role_font() const;
    const wxFont& detail_font() const;
    int  trailing_reserve() const;
    // Width of the slot-dot run and its "+n", gap to the label included; zero
    // without slot dots. Shared by measuring and painting.
    int  slot_dots_width() const;
    // Width of the leading text and its gap; zero without one.
    int  lead_width() const;
    // Screen rect of the row-action glyph, empty when there is none.
    wxRect row_action_rect() const;
    const ShellTheme& m_theme;
    HeaderStyle m_style;
    HeaderIcon m_icon;
    HeaderRowDecoration m_decoration;
    HeaderIcon m_row_action{HeaderIcon::None};
    wxString m_row_action_label;
    int m_label_cap{0};
    bool m_dark{false}, m_hover{false}, m_pressed{false}, m_status{false}, m_warning{false};
    bool m_menu_selected{false};
    bool m_attached{true};
    bool m_open{false};
    bool m_keyboard_activated{false};
};

struct HeaderMenuItem {
    wxString label;
    HeaderIcon icon{HeaderIcon::None};
    wxString detail;
    bool enabled{true};
    bool separator{false};
    std::function<void()> invoke;
    // A title row: an Eyebrow-styled caption that is never selectable and
    // never invokable. `label` carries the caption.
    bool title{false};
    // Keeps the popup open when invoked -- for a row that swaps the menu's own
    // contents (a sub-list, a back step) rather than finishing a task.
    bool keeps_open{false};
    // Secondary action at the row's right end. Icon actions appear on hover
    // and keep the popup open for a nested step; text actions can dismiss it.
    HeaderIcon row_action{HeaderIcon::None};
    std::function<void()> invoke_row_action;
    HeaderRowDecoration decoration;
    // The row's window name, which lookups and assistive technology read;
    // empty uses the label. Set when the row draws part of what it says
    // outside the label, as a slot row draws its number. Last, so rows
    // written positionally elsewhere stay as they are.
    wxString name;
    // A visible compact text button at the row's right edge. The row itself
    // can remain non-invokable; keyboard activation invokes the text action.
    wxString row_action_label;
    bool dismisses_on_row_action{false};
};

// A custom view among a menu's rows that takes part in the menu's keyboard
// model -- the filament menu's colour row. The menu moves into it with Up
// from the row below it (or Down from the row above), and out of it again the
// same way; while it is in, Left, Right, Return and Space are the view's.
class HeaderMenuKeyView
{
public:
    virtual ~HeaderMenuKeyView() = default;
    // Shows or hides the view's own focus mark.
    virtual void set_key_focus(bool focused) = 0;
    // Left, Right, Return or Space while the view has the keyboard. Returns
    // false for a key it does not use.
    virtual bool on_menu_key(int key_code) = 0;
    // The child the keyboard is on, for tests and assistive technology.
    virtual wxWindow* key_child() const = 0;
};

// Right-aligned transient menu. The popup owns only presentation; callbacks
// return to the owner after dismissal, never run commands inside mouse capture.
//
// A menu can also replace its own contents in place -- the filament menu's
// slot views do this rather than opening a second popup, so the popup keeps
// its position, its keyboard model, and its dismissal handling.
class HeaderMenu : public PopupWindow
{
public:
    HeaderMenu(wxWindow* parent, const ShellTheme& theme, bool dark,
               std::vector<HeaderMenuItem> items);
    // Which edge of the anchor the popup lines up with: Right opens under a
    // control at the window's right (the header), Left under one at its left
    // (the Plates pane), so a menu never opens toward the window's edge.
    enum class Align { Right, Left };
    void open(HeaderButton& anchor, Align align = Align::Right);
    HeaderButton* selected_item() const { return m_selected < 0 ? nullptr : m_items[m_selected]; }
    // The custom view, when it takes part in the keyboard model, and whether
    // the keyboard is in it now.
    HeaderMenuKeyView* key_view() const;
    bool               key_view_active() const { return m_header_active && key_view() != nullptr; }

    // Swaps the rows for a new set and re-lays out at the same anchor. The
    // width stays put so the popup does not jump as the person types.
    void replace_items(std::vector<HeaderMenuItem> items);
    // A custom view among the rows -- the filament menu's colour row. The
    // builder runs with the popup as parent; nullptr clears it.
    // `after_rows` places the custom view below that many rows, so a step can
    // keep its title/back row at the top where the design puts it.
    void set_header_builder(std::function<wxWindow*(wxWindow*)> builder, int after_rows = 0);
    // Invoked when the popup dismisses for any reason, after the anchor has
    // been released. Used to drop menu-owned state the owner is holding.
    void set_dismiss_listener(std::function<void()> listener) { m_dismissed = std::move(listener); }

