// A compact, chat-owned account of the setup: what the chat asked for, the
// selected presets, how the agent means to print (its plan's headline), and
// the estimates. Native code supplies the facts; this page presents them.
// Every setting, and what differs from the presets, is on the All settings panel.

import { ReactNode, useState } from 'react';
import { ChangeInfo, SliceEstimateInfo, WorkspaceContext } from '../bridge/protocol';

export interface SetupCardProps {
  context: WorkspaceContext | null;
  working?: boolean;
  historical?: boolean;
  savedAt?: string;
  agentAvailable?: boolean;
  changes?: ChangeInfo[];
  now?: number;
  estimateBefore?: SliceEstimateInfo | null;
  sent?: { at: string; printer: string };
  attention?: Finding[];
  onCompute?: () => void;
  onUndo?: (changeSeq: number) => void;
  onViewSetup?: () => void;
}

export function formatPrintTime(seconds: number): string {
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `~${minutes} min`;
  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
}

export function formatGrams(grams: number): string {
  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
}

export function formatCost(cost: number, currency: string): string {
  if (currency) {
    try {
      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
    } catch {
      // An unknown regional code does not make the native amount disappear.
    }
  }
  return `cost ${cost.toFixed(2)}`;
}

export function formatMoment(value: string | undefined): string {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, {
    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
  });
}

export const RECENT_CHANGE_MS = 60000;

export interface EstimateView {
  heading: string;
  metrics: { icon: string; text: string }[];
  cost: string;
