#pragma once

// What the Plates / Project pane shows, as plain data. No wx and no Orca types:
// the rows are a pure function of the workspace's outline and snapshot plus a
// little navigation state, so every rule about what appears, and when, is
// tested without a window. The pane (LeftPane) only paints these rows.

#include "slic3r/GUI/JusPrin/Workspace/ProjectOutline.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <cstdint>
#include <optional>
#include <set>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

enum class PaneTab : std::uint8_t { Plates, Project };

// Views inside the Project tab. Root is the tab itself; every other view is one
// level below it and returns to it.
enum class ProjectView : std::uint8_t { Root, Details, PrintHistory, Versions };

// Which tab and view are showing, and which objects the person has opened.
// The expansion set is project-scoped, so it is dropped whenever the project
// session changes, and a new project always starts on the Project root.
class PaneNavigation
{
public:
    PaneTab     tab() const { return m_tab; }
    ProjectView view() const { return m_view; }

    // A tab always lands on its top level, so Plates is the plate list and
    // Project is the Project root, whatever was showing before.
    void show_plates() { m_tab = PaneTab::Plates; m_view = ProjectView::Root; }
    void show_project() { m_tab = PaneTab::Project; m_view = ProjectView::Root; }

    void open(ProjectView view) { m_tab = PaneTab::Project; m_view = view; }
    // Goes up one Project level. False when there is nowhere to go up to, so
    // Escape at the Project root, or on the Plates tab, is left alone.
    bool back()
    {
        if (m_tab != PaneTab::Project || m_view == ProjectView::Root)
            return false;
        m_view = ProjectView::Root;
        return true;
    }

    bool is_expanded(Workspace::ObjectId id) const { return m_expanded.count(id) != 0; }
    void set_expanded(Workspace::ObjectId id, bool expanded)
    {
        if (expanded)
            m_expanded.insert(id);
        else
            m_expanded.erase(id);
    }
    void toggle_expanded(Workspace::ObjectId id) { set_expanded(id, !is_expanded(id)); }

    // Called with every snapshot. Returns true when the project changed.
    bool follow_session(Workspace::ProjectSessionId session)
    {
        if (session == m_session)
            return false;
        m_session = session;
        m_expanded.clear();
        m_view = ProjectView::Root;
        return true;
    }

private:
    PaneTab                       m_tab{PaneTab::Plates};
    ProjectView                   m_view{ProjectView::Root};
    Workspace::ProjectSessionId   m_session;
    std::set<Workspace::ObjectId> m_expanded;
};

struct PaneRow
{
    enum class Kind : std::uint8_t { Plate, Object, Copy, Volume, OffPlateHeader };

    Kind kind{Kind::Plate};
    int  depth{0};

    // Identity: the field that matches `kind` is set. An object row also
    // carries its plate, since the same object can be listed on several.
    Workspace::PlateId    plate;
    Workspace::ObjectId   object;
    Workspace::InstanceId copy;
    Workspace::VolumeId   volume;

    std::string name;
    bool        selected{false};
    bool        expandable{false};
    bool        expanded{false};

    // Plate rows.
    bool                    sliced{false};
    bool                    locked{false};
    bool                    custom_settings{false};
    Workspace::PlateSummary summary; // meaningful on a folded plate only

    // Object rows: the copies listed under this row, and how many of them
    // will not print. A disabled object makes all of them not print.
    std::size_t copies{0};
    std::size_t wont_print{0};
    bool        object_printable{true};
    std::optional<int> filament; // 1-based; set only when the assignment is worth showing
    std::string        filament_colour; // that slot's "#RRGGBB", when the profile names one

    // Copy rows: 1-based position among the object's copies, as listed.
    std::size_t ordinal{0};
    bool        copy_wont_print{false};
    bool        copy_printable{true};

    // Volume rows.
    Workspace::VolumeRole role{Workspace::VolumeRole::Part};

    // Object and volume rows. A customization is a choice the person made; a
    // mesh problem is a defect in the model. They never share a mark.
----- ProjectPaneModel
#pragma once

// What the Project tab shows, as plain data. Like LeftPaneModel it has no wx
// and no Orca types, and it states only what the owners recorded: the model's
// metadata comes from the 3MF's project details, the print history from the
// physical-print ledger. A field nobody recorded is absent here, never blank,
// zero, or guessed, so the pane has nothing to omit by hand.

#include "slic3r/GUI/JusPrin/Agent/ManufacturingHistory.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// The model's own words about itself, as 3MF carries them. The saved project's
// name is a different fact and is never a fallback for `title`.
struct ModelInfoView
{
    std::string title, designer, license, copyright, origin, description;
    std::string profile_title, profile_description;

    bool empty() const
    {
        return title.empty() && designer.empty() && license.empty() && copyright.empty() && origin.empty() &&
               description.empty() && profile_title.empty() && profile_description.empty();
    }
};

struct AttachmentGroup
{
    std::string                              folder; // Orca's category, such as "Model Pictures"
    std::vector<Workspace::ProjectAttachment> files;
};

// The Details view: only sections the file backs with data.
struct ProjectDetailsView
{
    ModelInfoView                model;
    std::vector<AttachmentGroup> attachments;
    bool                         attachments_truncated{false};

    bool empty() const { return model.empty() && attachments.empty(); }
};

ProjectDetailsView build_details_view(const Workspace::ProjectDetails& details);

enum class PrintOutcome : std::uint8_t { Completed, Failed, Cancelled, Unrecorded };

struct PrintHistoryEntry
{
    std::string  id;
    PrintOutcome outcome{PrintOutcome::Unrecorded};
    std::string  recorded_outcome;
    // Verbatim from the ledger (ISO 8601 UTC); the pane formats them.
    std::string  started_at, ended_at;
    // Present only when both timestamps parse and the end is not before the start.
    std::optional<std::int64_t> duration_seconds;
    std::string  plate_name, printer, material, failure;
    std::optional<int> stopped_percent;
    // The slicer's estimate when the build was made. It is a prediction, not a
    // measurement of the print, and a zero means nobody recorded it.
    std::optional<double> estimated_seconds, estimated_grams, estimated_cost;
};

struct PrintHistoryView
{
    std::size_t                    total{0};
    std::vector<PrintHistoryEntry> detailed; // newest first
    // Prints that were counted but left no facts to show.
    std::size_t                    count_only{0};
};

// `records` is the ledger as stored (oldest first). A record with no outcome,
// time, plate, printer or material has nothing to show beyond that it
// happened, so it is counted and not drawn as an empty row.
PrintHistoryView build_print_history(const std::vector<Agent::PhysicalPrintRecord>& records);

// Seconds between two ISO 8601 UTC timestamps ("2026-08-30T01:02:03Z"), or
// nullopt when either does not parse or the end precedes the start.
std::optional<std::int64_t> seconds_between(const std::string& start, const std::string& end);

} // namespace Slic3r::GUI::JusPrin

